using System.Collections.Generic;

namespace Automaton.AI.Interfaces;

/// <summary>
/// Response from an AI provider.
/// </summary>
public class AIResponse
{
    /// <summary>
    /// Text content generated by the AI.
    /// </summary>
    public string? Text { get; set; }

    /// <summary>
    /// Tool calls requested by the AI.
    /// </summary>
    public List<ToolCallRequest> ToolCalls { get; set; } = new();

    /// <summary>
    /// Reasoning or internal thoughts (if supported by provider).
    /// </summary>
    public string? Reasoning { get; set; }

    /// <summary>
    /// Finish reason from the provider.
    /// </summary>
    public string FinishReason { get; set; } = string.Empty;

    /// <summary>
    /// Usage statistics for the request.
    /// </summary>
    public AIUsage? Usage { get; set; }

    /// <summary>
    /// Set when the stream was cut short because the model was detected looping
    /// mid-response (see <c>StreamingLoopMonitor</c>). The response is partial:
    /// <see cref="Text"/> and <see cref="Reasoning"/> hold whatever had arrived,
    /// and <see cref="ToolCalls"/> is deliberately empty — a half-streamed call
    /// would carry truncated JSON arguments and an unpaired call id.
    /// </summary>
    public bool LoopAborted { get; set; }

    /// <summary>
    /// Human-readable description of the detected loop. Set only when
    /// <see cref="LoopAborted"/> is true.
    /// </summary>
    public string? LoopAbortDiagnosis { get; set; }

    /// <summary>
    /// Set when the provider reported <c>finish_reason: "length"</c> — the model
    /// ran out of output budget (<c>max_tokens</c>) mid-generation rather than
    /// choosing to stop. The response is partial in exactly the same sense as
    /// <see cref="LoopAborted"/>: whatever had arrived is kept, but any tool call
    /// whose streamed JSON arguments did not finish parsing is dropped.
    ///
    /// Without this flag a truncated turn is indistinguishable from a deliberate
    /// one — a reasoning-heavy model that spends its whole budget thinking yields
    /// empty visible text and no tool calls, so the agent loop concludes the
    /// assistant is finished and silently hands control back to the user.
    /// </summary>
    public bool Truncated { get; set; }

    /// <summary>
    /// The tools whose calls were dropped because the output limit cut their arguments off
    /// (see <see cref="Truncated"/>). The model does not know this happened - from its side it
    /// made the call - so the agent loop has to say so, or it makes the same oversized call again.
    /// </summary>
    public List<string> TruncatedToolCalls { get; set; } = new();

    /// <summary>
    /// The reasoning items a <c>/responses</c> endpoint returned, in order. The model needs them
    /// back on the next request of the same turn, or it starts each tool step without its own
    /// thinking. Empty for <c>/chat/completions</c>.
    /// </summary>
    public List<ProviderReasoningItem> ReasoningItems { get; set; } = new();

    /// <summary>
    /// Set when the endpoint reported a failure inside a stream that had started successfully
    /// (a <c>/responses</c> <c>response.failed</c> or <c>error</c> event).
    /// </summary>
    public string? StreamError { get; set; }
}

/// <summary>One reasoning item from a <c>/responses</c> reply, kept to send back unchanged.</summary>
public class ProviderReasoningItem
{
    [System.Text.Json.Serialization.JsonPropertyName("id")]
    public string? Id { get; set; }

    [System.Text.Json.Serialization.JsonPropertyName("encrypted_content")]
    public string? EncryptedContent { get; set; }
}

/// <summary>
/// Request to call a tool.
/// </summary>
public class ToolCallRequest
{
    /// <summary>
    /// Unique identifier for the tool call.
    /// </summary>
    public string Id { get; set; } = string.Empty;

    /// <summary>
    /// Tool to call.
    /// </summary>
    public string Tool { get; set; } = string.Empty;

    /// <summary>
    /// Arguments for the tool call as JSON.
    /// </summary>
    public string Arguments { get; set; } = string.Empty;
}

/// <summary>
/// Usage statistics for AI requests.
/// </summary>
public class AIUsage
{
    /// <summary>
    /// Number of input tokens used.
    /// </summary>
    public int InputTokens { get; set; }

    /// <summary>
    /// Number of output tokens generated.
    /// </summary>
    public int OutputTokens { get; set; }

    /// <summary>
    /// Total tokens used.
    /// </summary>
    public int TotalTokens { get; set; }
}
